mapper.select:
SELECT MEMBER_PW
FROM "MEMBER"
WHERE MEMBER_EMAIL = #{memberEmail}

SELECT MEMBER_PW
FROM "MEMBER"
WHERE MEMBER_NO = ${memberNo}

mapper.update:
UPDATE RECRUITMENT
SET RECRUIT_COMPLETE_FL = #{complete}
WHERE RECRUITMENT_NO = ${recruitmentNo}

mapper.select:
SELECT COUNT(*)
FROM "EMPLOYER"
WHERE MEMBER_NO = ${memberNo}
	AND BUSINESS_NICKNAME = #{businessNickname}

SELECT COUNT(*)
FROM "EMPLOYER"
WHERE MEMBER_NO = ${memberNo}
	AND BUSINESS_TEL = #{businessTel}

SELECT WORKTYPE_NO
FROM EMPLOYER_WORKTYPE
WHERE WORKTYPE_CATEGORY = #{category}

mapper.update:
UPDATE "EMPLOYER"
SET BUSINESS_NICKNAME = #{businessNickname},
	BUSINESS_TEL = #{businessTel},
	BUSINESS_ADDRESS = #{businessAddress}
WHERE EMPLOYER_NO = ${employerNo}

mapper.delete:
DELETE FROM "BUSINESS_IMG"
WHERE BUSINESS_IMG_ORDER IN (${deleteOrderList})
	AND EMPLOYER_NO = ${employerNo}

mapper.update:
UPDATE "BUSINESS_IMG"
SET BUSINESS_IMG_ORIGINAL_NAME = #{businessImgOriginalName},
	BUSINESS_IMG_RENAME = #{businessImgRename}
WHERE EMPLOYER_NO = ${employerNo}
	AND BUSINESS_IMG_ORDER = ${businessImgOrder}

mapper.select:
SELECT MEMBER_NO
FROM EMPLOYER
WHERE EMPLOYER_NO = ${employerNo}

SELECT RECRUITMENT_NO
FROM RECRUITMENT
WHERE MEMBER_NO = ${memberNo}

SELECT RESUME_NO
FROM RECRUITMENT_RESUME
WHERE RECRUITMENT_NO = ${recruitmentNo}

SELECT COUNT(*)
FROM RESUME_CAREER
WHERE RESUME_NO = ${resumeNo}
